function prepareLeisure(s){s.ambition=s.ambition||'profit';s.album=s.album||{};s.albumRewards=s.albumRewards||[];s.friendStories=s.friendStories||[];for(const id of Object.keys(s.met))if(relationship(s,+id)>=25&&!s.friendStories.includes(+id))s.friendStories.push(+id);if(s.closing&&!s.night)s.night={day:s.day,actions:2,done:[],report:[]};if(!s.closing)s.night=null}
function goals(s){const definitions=[['profit','돈을 모으는 가게',s.profit,[500,3000,10000,30000],'G','물건을 싸게 사서 판매하고 순이익을 남기세요.'],['collection','이야기를 모으는 가게',Object.keys(s.album||{}).length,[4,12,36,72,144],'종','새로운 진품을 보관해 마감 후 도록에 등록하세요.'],['friends','단골이 쉬어 가는 가게',chars().filter((_,i)=>relationship(s,i)>=25).length,[1,3,8,16,chars().length],'명','만족스러운 거래와 밤의 차 한 잔으로 가까워지세요.']];return definitions.map(([id,name,value,tiers,unit,tip])=>({id,name,value,tiers,unit,tip,target:tiers.find(n=>n>value)||tiers.at(-1),completed:tiers.filter(n=>value>=n).length,finished:value>=tiers.at(-1)}))}
function setAmbition(s,id){if(!['profit','collection','friends'].includes(id))return{ok:false,message:'선택할 수 없는 목표입니다.'};s.ambition=id;return{ok:true,message:'관심 목표를 바꿨습니다. 세 가지 기록은 모두 함께 쌓입니다.'}}
